window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6ebfb0dcccc0c540"]={"versions": [{"id": "FIG-6ebfb0dcccc0c540", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und API-Aufrufbaum-Diagramm (Call Tree) für den AUTOSAR Classic Platform Crypto-Stack. Das Diagramm visualisiert die vertikale Schichtenarchitektur und den Kontrollfluss zwischen Crypto Service Manager (CSM, System Services), Crypto Interface (CryIf, BSW-Schnittstellenschicht) und Crypto Driver (Crypto, Microcontroller Abstraction Layer / MCAL), unterteilt in die zwei Interaktionspfade „Job based API“ und „Direct API“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei horizontale Schichten (Farbblöcke) und zwei vertikale Spalten:</p>\n<ul class=\"fig-list\">\n<li>Schichten (von oben nach unten):</li>\n<li>CSM-Ebene (oberer blauer Block): Anwendungsnahe Service-Schicht.</li>\n<li>CryIf-Ebene (mittlerer grüner Block): Crypto Interface zur Abstraktion und Weiterleitung.</li>\n<li>Crypto-Ebene (unterer roter Block): Treiber-/Hardware-Schicht.</li>\n<li>Spalten und Schnittstellen:</li>\n<li><strong>Job based API</strong>:</li>\n<li>CSM-Funktionen: <code>Csm_Hash()</code>, <code>Csm_MacGenerate()</code>, <code>Csm_MacVerify()</code>, <code>Csm_Encrypt()</code>, <code>Csm_Decrypt()</code>, <code>Csm_JobKeySetValid()</code>, <code>...</code></li>\n<li>Datenstruktur/Parameter: <code>Csm_JobType job</code></li>\n<li>CryIf-Funktion: <code>CryIf_ProcessJob(job)</code></li>\n<li>Crypto-Funktion: <code>Crypto_ProcessJob(job)</code></li>\n<li><strong>Direct API</strong>:</li>\n<li>CSM-Funktionen: <code>Csm_KeySetValid()</code>, <code>Csm_KeyElementGet()</code>, <code>Csm_KeyElementSet()</code>, <code>Csm_KeyDerive()</code>, <code>...</code></li>\n<li>CryIf-Funktionen: <code>CryIf_KeySetValid()</code>, <code>CryIf_KeyElementGet()</code>, <code>CryIf_KeyElementSet()</code>, <code>CryIf_KeyDerive()</code>, <code>...</code></li>\n<li>Crypto-Funktionen: <code>Crypto_KeySetValid()</code>, <code>Crypto_KeyElementGet()</code>, <code>Crypto_KeyElementSet()</code>, <code>Crypto_KeyDerive()</code>, <code>...</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Job-basierter Pfad</strong>: Aufrufe kryptografischer Berechnungs- und asynchroner/job-basierter Operationen im CSM (<code>Csm_Hash()</code>, <code>Csm_MacGenerate()</code> etc.) kapseln die Anfrage in ein Job-Objekt vom Typ <code>Csm_JobType job</code>. Dieses wird über den einheitlichen Durchstich <code>CryIf_ProcessJob(job)</code> an das Crypto Interface und von dort an den Treiber über <code>Crypto_ProcessJob(job)</code> durchgereicht.</li>\n<li><strong>Direkter Pfad</strong>: Direkte Schlüssel- und Key-Management-Operationen (<code><em>KeySetValid()</code>, <code></em>KeyElementGet()</code>, <code><em>KeyElementSet()</code>, <code></em>KeyDerive()</code>) werden 1:1 direkt und synchron ohne Kapselung in einen generischen Job von CSM über CryIf an das Crypto-Treibermodul weitergeleitet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für das Architekturdesign und API-Mapping des AUTOSAR Crypto-Stacks:</p>\n<ul class=\"fig-list\">\n<li>Kryptografische Primitiven und rechenintensive Operationen müssen über das einheitliche Job-Schema (<code>Csm_JobType</code>) und <code>ProcessJob()</code> abgewickelt werden.</li>\n<li>Key-Management-Funktionen werden als Direct API synchron durch die Schichten geschleift, wobei Namenskonventionen und Parameterstrukturen schichtenübergreifend symmetrisch korrespondieren (<code>Csm_<em></code>, <code>CryIf_</em></code>, <code>Crypto_*</code>).</li>\n<li>Das Diagramm grenzt strikt ab, welche Funktionsgruppen job-basiert orchestriert und welche direkt auf Treiberebene geroutet werden.</li>\n</ul>"}, {"id": "FIG-d8d4f68fc03ff68b", "releases": ["R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und API-Aufrufbaum-Diagramm (Call Tree) für den AUTOSAR Classic Platform Crypto-Stack. Das Diagramm visualisiert die vertikale Schichtenarchitektur und den Kontrollfluss zwischen Crypto Service Manager (CSM, System Services), Crypto Interface (CryIf, BSW-Schnittstellenschicht) und Crypto Driver (Crypto, Microcontroller Abstraction Layer / MCAL), unterteilt in die zwei Interaktionspfade „Job based API“ und „Direct API“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei horizontale Schichten (Farbblöcke) und zwei vertikale Spalten:</p>\n<ul class=\"fig-list\">\n<li>Schichten (von oben nach unten):</li>\n<li>CSM-Ebene (oberer blauer Block): Anwendungsnahe Service-Schicht.</li>\n<li>CryIf-Ebene (mittlerer grüner Block): Crypto Interface zur Abstraktion und Weiterleitung.</li>\n<li>Crypto-Ebene (unterer roter Block): Treiber-/Hardware-Schicht.</li>\n<li>Spalten und Schnittstellen:</li>\n<li><strong>Job based API</strong>:</li>\n<li>CSM-Funktionen: <code>Csm_Hash()</code>, <code>Csm_MacGenerate()</code>, <code>Csm_MacVerify()</code>, <code>Csm_Encrypt()</code>, <code>Csm_Decrypt()</code>, <code>Csm_JobKeySetValid()</code>, <code>...</code></li>\n<li>Datenstruktur/Parameter: <code>Csm_JobType job</code></li>\n<li>CryIf-Funktion: <code>CryIf_ProcessJob(job)</code></li>\n<li>Crypto-Funktion: <code>Crypto_ProcessJob(job)</code></li>\n<li><strong>Direct API</strong>:</li>\n<li>CSM-Funktionen: <code>Csm_KeySetValid()</code>, <code>Csm_KeyElementGet()</code>, <code>Csm_KeyElementSet()</code>, <code>Csm_KeyDerive()</code>, <code>...</code></li>\n<li>CryIf-Funktionen: <code>CryIf_KeySetValid()</code>, <code>CryIf_KeyElementGet()</code>, <code>CryIf_KeyElementSet()</code>, <code>CryIf_KeyDerive()</code>, <code>...</code></li>\n<li>Crypto-Funktionen: <code>Crypto_KeySetValid()</code>, <code>Crypto_KeyElementGet()</code>, <code>Crypto_KeyElementSet()</code>, <code>Crypto_KeyDerive()</code>, <code>...</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Job-basierter Pfad</strong>: Aufrufe kryptografischer Berechnungs- und asynchroner/job-basierter Operationen im CSM (<code>Csm_Hash()</code>, <code>Csm_MacGenerate()</code> etc.) kapseln die Anfrage in ein Job-Objekt vom Typ <code>Csm_JobType job</code>. Dieses wird über den einheitlichen Durchstich <code>CryIf_ProcessJob(job)</code> an das Crypto Interface und von dort an den Treiber über <code>Crypto_ProcessJob(job)</code> durchgereicht.</li>\n<li><strong>Direkter Pfad</strong>: Direkte Schlüssel- und Key-Management-Operationen (<code><em>KeySetValid()</code>, <code></em>KeyElementGet()</code>, <code><em>KeyElementSet()</code>, <code></em>KeyDerive()</code>) werden 1:1 direkt und synchron ohne Kapselung in einen generischen Job von CSM über CryIf an das Crypto-Treibermodul weitergeleitet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für das Architekturdesign und API-Mapping des AUTOSAR Crypto-Stacks:</p>\n<ul class=\"fig-list\">\n<li>Kryptografische Primitiven und rechenintensive Operationen müssen über das einheitliche Job-Schema (<code>Csm_JobType</code>) und <code>ProcessJob()</code> abgewickelt werden.</li>\n<li>Key-Management-Funktionen werden als Direct API synchron durch die Schichten geschleift, wobei Namenskonventionen und Parameterstrukturen schichtenübergreifend symmetrisch korrespondieren (<code>Csm_<em></code>, <code>CryIf_</em></code>, <code>Crypto_*</code>).</li>\n<li>Das Diagramm grenzt strikt ab, welche Funktionsgruppen job-basiert orchestriert und welche direkt auf Treiberebene geroutet werden.</li>\n</ul>"}], "trans": [{"from": "FIG-6ebfb0dcccc0c540", "to": "FIG-d8d4f68fc03ff68b", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
